static const char s_digit_chars[] = "0123456789.+-Ee%mukKMWVOhDAC?RFLHzs";

const uint8_t *font_digit_bitmap(char c)
{
    uint16_t i;
    for (i = 0u; i < FONT_DIGIT_CHAR_COUNT; i++) {
        if (s_digit_chars[i] == c) {
            return s_digit_bitmaps[i];
        }
    }
    return (const uint8_t *)0;
}

const uint8_t *font_digit_symbol_bitmap(uint8_t sym)
{
    if (sym < FONT_DIGIT_SYM_COUNT) {
        return s_digit_symbols[sym];
    }
    return (const uint8_t *)0;
}

uint16_t font_digit_width(void)
{
    return FONT_DIGIT_WIDTH;
}

uint16_t font_digit_height(void)
{
    return FONT_DIGIT_HEIGHT;
}

/* ---------------------------------------------------------------------------
 * RIF lookup helpers (hand-maintained section: the generator owns the
 * bitmaps above; these map ASCII/symbols to RIF directory identities).
 * --------------------------------------------------------------------------- */

bool font_digit_rif_code(char c, uint32_t *kind, uint16_t *code)
{
    uint16_t i;

    if (kind == 0 || code == 0) {
        return false;
    }
    for (i = 0u; s_digit_chars[i] != '\0'; i++) {
        if (s_digit_chars[i] == c) {
            *kind = RIF_KIND_DIGIT_CHAR;
            *code = (uint8_t)c;
            return true;
        }
    }
    return false;
}

bool font_digit_rif_symbol_code(uint8_t symbol, uint32_t *kind, uint16_t *code)
{
    if (kind == 0 || code == 0 || symbol >= FONT_DIGIT_SYM_COUNT) {
        return false;
    }
    *kind = RIF_KIND_DIGIT_SYMBOL;
    *code = symbol;
    return true;
}
